s = obs['state']
action = {'left_ee_pose': list(s['left_ee_pose']), 'right_ee_pose': list(s['right_ee_pose']), 'left_ee_joint_state': list(s['left_ee_joint_state']), 'right_ee_joint_state': [0.0]}
for i in range(8):
    obs, reward, terminated, truncated, info = step(action)
    if terminated or truncated:
        break
print({'steps': i + 1, 'success': info.get('success', False), 'pose': list(obs['state']['right_ee_pose'])})

